import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { moduleTierOf, pageDescription } from "./docs-text.ts";

describe("pageDescription", () => {
  it("takes the first paragraph in plain text", () => {
    assert.equal(
      pageDescription(
        "# Title\n\nUse `saasaloy add` to [add](x.md) a **module**.\n\nSecond."
      ),
      "Use saasaloy add to add a module."
    );
  });

  it("skips the generated banner and the comment", () => {
    assert.equal(
      pageDescription(
        "<!-- x -->\n\n# email\n\n> Generated by a script.\n\nA workspace.\n"
      ),
      "A workspace."
    );
  });

  it("cuts a long paragraph at a word", () => {
    const out = pageDescription(`${"word ".repeat(80)}`);
    assert.ok(out.length <= 160 && out.endsWith("…"));
  });
});

describe("moduleTierOf", () => {
  it("reads the tier from the Facts table", () => {
    assert.equal(
      moduleTierOf("| Field | Value |\n|---|---|\n| Tier | capability |\n"),
      "capability"
    );
    assert.equal(moduleTierOf("no table"), undefined);
  });
});
